 function byArea(){
  const arr=window.pfDiseaseEntries||[];
  const map={};arr.forEach((x,i)=>{const k=x.group||x.system||'Weitere Themen';(map[k]??=[]).push({x,i})});
  return map
 }
 function dueCount(){return Object.values(state.reviewItems).filter(x=>x.due<=dateKey()).length}
 function renderTodayOnHome(c){const due=dueCount();const box=document.createElement('div');box.className='panel';box.innerHTML='<span class="tag">Dein Lernstand</span><h2>Heute weiterlernen</h2><p>'+ (due?due+' Wiederholungen sind fällig.':'Starte mit einer kurzen Lerneinheit aus deinen Themen.')+'</p><button class="btn primary" onclick="go(&quot;plan&quot;)">Zum persönlichen Lernweg</button>';c.appendChild(box)}
 function renderLearningPlan(c){
  const due=dueCount(),done=Object.keys(state.done||{}).filter(k=>state.done[k]).length,areas=byArea(),weak=Object.keys(state.reviewItems).filter(k=>state.reviewItems[k].rating!=='gewusst');
  const next=due?'<button class="btn primary" onclick="go(&#39;themenquiz&#39;)">Unsichere Fragen wiederholen ('+due+')</button>':
   '<button class="btn primary" onclick="go(&#39;themenquiz&#39;)">Mit einem kurzen Themenquiz starten</button>';
  c.innerHTML='<div class="panel"><span class="tag">Dein Lernweg · individuell aus deinem Lernstand</span><h2>Heute weiterlernen</h2><p>Dieser Lernweg richtet sich nach deinen eigenen Antworten und deinem Fortschritt. Er enthält keinen persönlichen Prüfungsmonat oder vorgegebenen Kalender.</p><div class="grid"><div class="card"><strong>'+due+'</strong><p>heute fällige Wiederholungen</p></div><div class="card"><strong>'+done+'</strong><p>als gelernt markierte Themen</p></div><div class="card"><strong>'+weak.length+'</strong><p>unsichere oder falsche Themen</p></div></div>'+next+'</div><div class="panel"><h3>Deine Themenstrecken</h3><p>Wähle ein Organsystem oder einen Pflegebereich. Eine Einheit besteht aus Wissen, einer Frage und einer kurzen Wiederholung.</p><div class="grid">'+Object.entries(areas).map(([k,v])=>'<article class="card"><h3>'+esc(k)+'</h3><p>'+v.length+' Lernprofile · '+v.filter(y=>state.reviewItems['disease-'+y.i]?.rating==='gewusst').length+' sicher markiert</p><button class="btn" onclick="upgradeQuizArea(&#39;'+esc(k).replace(/'/g,'&#39;')+'&#39;)">Einheit beginnen</button><button class="btn" onclick="upgradeCacheModule()">Modul offline speichern</button><span id="offlineStatus" class="muted"></span></article>').join('')+'</div></div><div class="panel"><h3>Dein nächster sinnvoller Schritt</h3><ol><li>Fällige Karten und Fragen beantworten.</li><li>Ein Krankheitsbild aus einem noch unsicheren Bereich bearbeiten.</li><li>Eine Prüfungs- oder Praxisübung auswählen und danach die Begründungen vergleichen.</li></ol></div>';
 }
 window.upgradeCacheModule=async function(){const label=document.querySelector('.offlineStatus');try{if(!('caches' in window)){if(label)label.textContent='Offline-Speichern wird von diesem Browser nicht unterstützt.';return}if(label)label.textContent='Lerneinheit wird gespeichert …';const cache=await caches.open('pflegefokus-module-offline-v1');await cache.addAll(['./index.html','./disease-library.js?v=3','./library.js?v=11','./learning-upgrade.js?v=1','./assets/heart-study.webp','./assets/lung-study.webp','./assets/glucose-study.webp','./assets/atmung-schema.svg','./assets/haut-schema.svg']);if(label)label.textContent='Texte, Quiz und lokale Abbildungen sind offline verfügbar. Externe Bilder benötigen Internet.'}catch(e){if(label)label.textContent='Speichern nicht möglich – prüfe die Internetverbindung und versuche es erneut.'}};
 window.upgradeQuizArea=function(area){state.upgradeArea=area;safeSave();go('themenquiz')};
 let qrun=[],qpos=0,qselected=null,qchecked=false;
 function quizPool(){
  const ds=window.pfDiseaseEntries||[];
  let a=ds.map((d,i)=>{const z=d.quiz;return z?{id:'disease-'+i,area:d.group||d.system||'Krankheitsbilder',q:z[0],options:z[1],answer:z[2],explain:z[3],title:d.title}:null}).filter(Boolean);
  if(typeof questions!=='undefined')a=a.concat(questions.map((q,i)=>({id:'general-'+i,area:'Pflegewissen und Modelle',q:q[0],options:q[1],answer:q[2],explain:q[3]})));
  if(typeof competencyBank!=='undefined')a=a.concat(competencyBank.map(q=>({id:'competency-'+q.id,area:q.kb,q:q.q,options:q.options,answer:q.answer,explain:q.explain})));
  const lib=window.libraryEntries||[];
  a=a.concat(lib.filter(x=>x.quiz).map((x,i)=>({id:'lib-'+i,area:x.category||'Pflegewissen',q:x.quiz[0],options:x.quiz[1],answer:x.quiz[2],explain:x.quiz[3],title:x.title})));
  return a;
 }
 function rateQuestion(q,rating){
  const prev=state.reviewItems[q.id]||{interval:0,streak:0};
  const days=rating==='gewusst'?Math.min(30,Math.max(1,prev.interval?prev.interval*2:2)):rating==='unsicher'?1:0;
  state.reviewItems[q.id]={rating:rating,interval:days,streak:rating==='gewusst'?prev.streak+1:0,due:new Date(Date.now()+days*86400000).toISOString().slice(0,10),updated:dateKey()};
  const area=q.area||'Andere';state.upgradeStats[area]??={attempts:0,correct:0};state.upgradeStats[area].attempts++;if(rating==='gewusst')state.upgradeStats[area].correct++;
  safeSave();
 }
 function renderQuiz(c){
  const pool=quizPool(),areas=[...new Set(pool.map(x=>x.area))],filter=state.upgradeArea||'Alle',list=pool.filter(x=>filter==='Alle'||x.area===filter),due=list.filter(x=>state.reviewItems[x.id]&&state.reviewItems[x.id].due<=dateKey());
  if(!qrun.length||qpos>=qrun.length){
   c.innerHTML='<div class="panel"><span class="tag">Themenquiz · Krankheitsbilder und Lerninhalte</span><h2>Gezielt üben</h2><p>Die Fragen kommen aus den thematischen Profilen. Nach jeder Antwort bewertest du deine Sicherheit; Fehler werden automatisch früher wiederholt.</p><label for="upgradeArea">Themenbereich</label><select id="upgradeArea" onchange="state.upgradeArea=this.value"><option>Alle</option>'+areas.map(x=>'<option '+(filter===x?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select><div class="flex"><button class="btn primary" onclick="upgradeQuizStart(false)">Quiz starten ('+list.length+' Fragen)</button><button class="btn" onclick="upgradeQuizStart(true)" '+(due.length?'':'disabled')+'>Fällige Wiederholungen ('+due.length+')</button></div></div>';
   return;
  }
  const q=qrun[qpos],ans=qselected!==null&&qselected===q.answer;
  let feedback='';
  if(qchecked){
   feedback='<p class="'+(ans?'good':'bad')+'"><strong>'+(ans?'Richtig':'Noch nicht richtig')+'</strong> '+esc(q.explain)+'</p><p>Wie sicher warst du?</p><div class="flex"><button class="btn" onclick="upgradeRate(0)">Nicht gewusst</button><button class="btn" onclick="upgradeRate(1)">Unsicher</button>';
   if(ans)feedback+='<button class="btn primary" onclick="upgradeRate(2)">Gewusst</button>';
   else feedback+='<p class="muted">Die falsche Antwort wird als Wiederholung vorgemerkt.</p>';
   feedback+='</div>';
  }else{
   feedback='<button class="btn primary" '+(qselected===null?'disabled':'')+' onclick="upgradeQuizCheck()">Antwort prüfen</button>';
  }
  c.innerHTML='<div class="panel"><span class="tag">'+esc(q.area)+' · '+(qpos+1)+' / '+qrun.length+'</span><h2>'+esc(q.q)+'</h2>'+q.options.map((x,i)=>'<button class="option '+(qselected===i?'selected':'')+'" '+(qchecked?'disabled':'')+' onclick="upgradeQuizAnswer('+i+')">'+String.fromCharCode(65+i)+' · '+esc(x)+'</button>').join('')+feedback+'</div>';
 }
 window.upgradeQuizStart=function(onlyDue){const area=state.upgradeArea||'Alle';qrun=quizPool().filter(q=>(area==='Alle'||q.area===area)&&(!onlyDue||(state.reviewItems[q.id]&&state.reviewItems[q.id].due<=dateKey()))).sort(()=>Math.random()-.5);qpos=0;qselected=null;qchecked=false;renderQuiz($('#content'))};
 window.upgradeQuizAnswer=n=>{if(!qchecked){qselected=n;renderQuiz($('#content'))}};
 window.upgradeQuizCheck=()=>{if(qselected!==null){qchecked=true;renderQuiz($('#content'))}};
 window.upgradeRate=r=>{const rating=['nicht gewusst','unsicher','gewusst'][r]||r;rateQuestion(qrun[qpos],rating);qpos++;qselected=null;qchecked=false;renderQuiz($('#content'))};

 function addFlashcardRatings(){if(typeof cards==='undefined')return;const c=$('#content');if(!c||document.getElementById('flashcardRating'))return;const row=document.createElement('div');row.id='flashcardRating';row.className='panel';const key='flashcard-'+ci,known=state.reviewItems[key];const disabled=flipped?'':'disabled';row.innerHTML='<span class="tag">Wiederholung</span><h3>Wie sicher konntest du diese Karte beantworten?</h3><p class="muted">Die Antwort erst aufdecken, dann deine Sicherheit einschätzen.</p><div class="flex"><button class="btn" '+disabled+' onclick="upgradeCardRate(0)">Nicht gewusst</button><button class="btn" '+disabled+' onclick="upgradeCardRate(1)">Unsicher</button><button class="btn primary" '+disabled+' onclick="upgradeCardRate(2)">Gewusst</button></div>'+(known?'<p class="muted">Nächste Wiederholung: '+esc(known.due)+'</p>':'');c.appendChild(row)}
 window.upgradeCardRate=r=>{const rating=['nicht gewusst','unsicher','gewusst'][r];rateQuestion({id:'flashcard-'+ci,area:'Lernkarten'},rating);if(typeof window.renderCards==='function')window.renderCards()};
 function renderReviewQueue(c){const quizDue=quizPool().filter(q=>state.reviewItems[q.id]&&state.reviewItems[q.id].due<=dateKey()),cardDue=typeof cards==='undefined'?[]:cards.map((x,i)=>({x,i})).filter(y=>state.reviewItems['flashcard-'+y.i]&&state.reviewItems['flashcard-'+y.i].due<=dateKey());c.innerHTML='<div class="panel"><span class="tag">Fällige Wiederholungen</span><h2>Wiederholen, was bald vergessen werden könnte</h2><p>Unsichere und falsche Fragen kommen früher wieder. Karteikarten werden nach deiner Selbsteinschätzung geplant.</p><p><strong>'+quizDue.length+'</strong> fällige Fragen · <strong>'+cardDue.length+'</strong> fällige Karten</p>'+ (quizDue.length?'<button class="btn primary" onclick="upgradeQuizStart(true)">Fällige Fragen starten</button>':'')+'</div>'+(cardDue.length?'<div class="panel"><h3>Fällige Lernkarten</h3>'+cardDue.map(y=>'<div class="card"><strong>'+esc(y.x[0])+'</strong><p><button class="btn" onclick="ci='+y.i+';flipped=false;go(\'karten\')">Karte öffnen</button></p></div>').join('')+'</div>':'')}

 function renderDashboard(c){
  const stats=state.upgradeStats||{},due=dueCount(),areas=Object.entries(stats),all=areas.reduce((a,[,s])=>({attempts:a.attempts+s.attempts,correct:a.correct+s.correct}),{attempts:0,correct:0});
  c.innerHTML='<div class="panel"><span class="tag">Wissensstand</span><h2>Was sitzt schon – was braucht Wiederholung?</h2><div class="grid"><div class="card"><strong>'+all.attempts+'</strong><p>beantwortete Fragen</p></div><div class="card"><strong>'+(all.attempts?Math.round(all.correct/all.attempts*100):0)+'%</strong><p>selbst als gewusst bewertet</p></div><div class="card"><strong>'+due+'</strong><p>heute fällige Wiederholungen</p></div></div><p>„Gewusst“ ist deine Selbsteinschätzung, kein offizielles Prüfungsergebnis. Unsichere Inhalte bleiben sichtbar und kommen zeitnah wieder.</p></div><div class="panel"><h3>Nach Themenbereich</h3>'+(areas.length?'<div class="grid">'+areas.map(([k,s])=>'<article class="card"><strong>'+esc(k)+'</strong><p>'+s.correct+' von '+s.attempts+' als gewusst markiert</p><div class="progress"><div style="width:'+(s.attempts?Math.round(s.correct/s.attempts*100):0)+'%"></div></div></article>').join('')+'</div>':'<p>Nach deinen ersten Quizantworten wird hier dein persönlicher Stand angezeigt.</p>')+'<button class="btn primary" onclick="go(&#39;themenquiz&#39;)">Jetzt gezielt üben</button></div>';
 }
 const scenarios=[
  {title:'Plötzliche Atemnot im Pflegeheim',setting:'Langzeitpflege',story:'Beim Rundgang sitzt Frau B. 81 Jahre plötzlich nach vorn gebeugt auf der Bettkante. Sie ringt nach Luft, kann nur einzelne Worte sprechen und wirkt ängstlich. Die Haut ist blass. Ein Inhalator liegt auf dem Nachttisch; ob er verordnet und korrekt anzuwenden ist, muss geprüft werden. Eine Pflegehilfskraft möchte sie flach hinlegen. Die aktuelle Atemfrequenz, Sauerstoffsättigung und der übliche Zustand sind noch nicht bekannt.',steps:[
   {q:'Was ist jetzt der erste sichere Schwerpunkt?',opts:['Bei der Person bleiben, Hilfe organisieren und Atmung/Bewusstsein unmittelbar beurteilen','Sie allein lassen und zuerst die vollständige Akte suchen','Sie gegen ihren Willen flach hinlegen','Ohne Prüfung ein fremdes Medikament geben'],a:0,why:'Akute Atemnot kann lebensbedrohlich sein. Unmittelbare Einschätzung und Alarmierung gehen vor Aktenrecherche; Position und Maßnahmen werden an Zustand und Wunsch angepasst.'},
   {q:'Welche Information erhebst du als Nächstes zügig?',opts:['Atemfrequenz, Atemarbeit, Bewusstsein, Hautfarbe und verfügbare SpO₂ im Verlauf','Nur die Trinkmenge der letzten Woche','Nur den Pflegegrad','Erst die Körpergröße'],a:0,why:'Atemmuster, Bewusstsein und Kreislaufzeichen helfen, die Dringlichkeit einzuschätzen. Messwerte ergänzen die klinische Beobachtung, ersetzen sie aber nicht.'},
   {q:'Wie reagierst du auf den Wunsch nach dem Inhalator?',opts:['Verordnung, Identität, Anwendung und individuellen Notfallplan prüfen; geeignete Hilfe nach Kompetenz organisieren','Beliebigen Inhalator verwenden','Alle Medikamente absetzen','Warten, bis die nächste Schicht kommt'],a:0,why:'Medikamente werden nicht beliebig gegeben. Verordnung, Identität, sichere Anwendung und Zuständigkeit prüfen und bei Verschlechterung unverzüglich eskalieren.'}
  ]},
  {title:'Akute Verwirrtheit und Fieber auf Station',setting:'Krankenhaus',story:'Herr K. 76 Jahre ist seit zwei Tagen wegen einer Harnwegsinfektion stationär. Am Abend erkennt er den Raum nicht, versucht aufzustehen und sagt, fremde Menschen seien im Zimmer. Die Temperatur ist erhöht; aktuelle Vitalwerte, Schmerz, Flüssigkeitsaufnahme und Medikamentenänderungen sind noch nicht systematisch erhoben. Seine Tochter berichtet, dass er morgens zu Hause noch klar wirkte.',steps:[
   {q:'Welche Einordnung ist am wichtigsten?',opts:['Neue akute Veränderung ernst nehmen und zeitnah strukturiert beurteilen','Die Verwirrtheit sofort als dauerhafte Demenz festlegen','Nur die Tochter beruhigen und Herrn K. ignorieren','Den nächsten Tag abwarten'],a:0,why:'Ein akuter Beginn kann auf Delir oder eine andere behandelbare Verschlechterung hinweisen. Ursachen und Gefährdungen müssen zeitnah im Team geprüft werden.'},
   {q:'Was folgt für die Sicherheit und Einschätzung?',opts:['Bei ihm bleiben, Sturzgefahr minimieren, Vitalzeichen und mögliche Ursachen erfassen, Hilfe informieren','Sofort ein Bettgitter ohne Prüfung anordnen','Ihn allein zur Toilette gehen lassen','Flüssigkeit und Medikamente pauschal entziehen'],a:0,why:'Sicherheit, Beobachtung und Ursachenklärung sind nötig. Freiheitsbeschränkende Maßnahmen sind keine automatische Standardlösung.'},
   {q:'Welche Übergabe hilft dem Team?',opts:['Zeitpunkt des Beginns, Abweichung vom Ausgangszustand, Beobachtungen, Vitalwerte, Medikamente und Maßnahmen strukturiert mitteilen','Nur „war komisch“ sagen','Ausschließlich die Diagnose vermuten','Die Dokumentation erst am Folgetag ergänzen'],a:0,why:'Eine präzise strukturierte Übergabe unterstützt rasche Beurteilung und Kontinuität. Vermutungen als solche kennzeichnen.'}
  ]}
 ];
 let sim=0,simStep=0,simFeedback=false,simOutcome=false;
 function renderSimulator(c){
  const s=scenarios[sim];
  if(simOutcome){const choices=s.steps.map((x,i)=>state.simChoices&&state.simChoices[sim+'-'+i]);const ending=choices[0]===false?'Die erste Priorität wurde verfehlt. In einer realen Lage wäre eine verzögerte Ersteinschätzung gefährlich; der Lernpunkt ist, zuerst Zustand und Dringlichkeit zu erfassen und sofort angemessene Hilfe zu organisieren.':choices.includes(false)?'Mindestens eine Entscheidung hätte die Abklärung verzögern oder ein vermeidbares Risiko schaffen können. Der Verlauf muss erneut beurteilt und das Team informiert werden.':'Die Dringlichkeit wurde zeitnah erkannt und die Einschätzung strukturiert fortgeführt. Der sichere Verlauf setzt trotzdem laufende Neubewertung und Teamkommunikation voraus.';c.innerHTML='<div class="panel"><span class="tag">Szenario-Ausgang · '+esc(s.setting)+'</span><h2>'+esc(s.title)+'</h2><p>'+ending+'</p><p>Fiktive Lernfolge zur Reflexion – keine Vorhersage eines echten klinischen Verlaufs.</p><button class="btn primary" onclick="upgradeSimRestart()">Szenario erneut üben</button><button class="btn" onclick="upgradeSimSelect('+((sim+1)%scenarios.length)+')">Anderes Szenario</button></div>';return}
  const step=s.steps[simStep];
  c.innerHTML='<div class="panel"><span class="tag">Verzweigtes Notfalltraining · fiktiver Übungsfall</span><h2>Entscheidungen mit Folgen üben</h2><p>Wähle zuerst eine Handlung. Der Fall reagiert auf deine Entscheidung; danach bekommst du die fachliche Begründung. Das ersetzt keinen lokalen Notfallstandard.</p><div class="flex">'+scenarios.map((x,i)=>'<button class="btn '+(i===sim?'primary':'')+'" onclick="upgradeSimSelect('+i+')">'+esc(x.setting)+'</button>').join('')+'</div><div class="card"><h3>'+esc(s.title)+'</h3><p>'+esc(s.story)+'</p><span class="tag">Schritt '+(simStep+1)+' von '+s.steps.length+'</span><h3>'+esc(step.q)+'</h3>'+step.opts.map((o,i)=>'<button class="option" '+(simFeedback?'disabled':'')+' onclick="upgradeSimChoose('+i+')">'+esc(o)+'</button>').join('')+(simFeedback?'<div class="learn-box"><strong>'+esc(state.simResults[sim+'-'+simStep]||'Entscheidung gespeichert')+'</strong><p>'+esc(step.why)+'</p><button class="btn primary" onclick="upgradeSimNext()">'+(simStep+1<s.steps.length?'Nächste Entscheidung':'Szenario abschließen')+'</button></div>':'')+'</div>';
 }
 window.upgradeSimSelect=i=>{sim=i;simStep=0;simFeedback=false;simOutcome=false;state.simChoices??={};Object.keys(state.simChoices).filter(k=>k.startsWith(i+'-')).forEach(k=>delete state.simChoices[k]);renderSimulator($('#content'))};
 window.upgradeSimRestart=()=>window.upgradeSimSelect(sim);
 window.upgradeSimChoose=i=>{if(simFeedback)return;const s=scenarios[sim],step=s.steps[simStep],ok=i===step.a;state.simResults[sim+'-'+simStep]=ok?'Du hast die passende Priorität gewählt.':'Hier gibt es einen wichtigen Lernpunkt.';state.simChoices??={};state.simChoices[sim+'-'+simStep]=ok;safeSave();simFeedback=true;renderSimulator($('#content'))};
 window.upgradeSimNext=()=>{if(simStep+1>=scenarios[sim].steps.length){simFeedback=false;simOutcome=true}else{simStep++;simFeedback=false}renderSimulator($('#content'))};

 const challenges=[
  {title:'Händehygiene im Pflegealltag',steps:[['Wann ist die hygienische Händedesinfektion erforderlich?',['Vor aseptischen Tätigkeiten und nach relevanten Kontaminationssituationen','Nur am Dienstbeginn','Nur bei sichtbarem Schmutz','Nur nach dem Essen'],0,'Die Indikationen richten sich nach den fünf Momenten und dem lokalen Hygieneplan. Sichtbarer Schmutz erfordert zusätzlich Waschen.'],['Was ist bei der Durchführung entscheidend?',['Ausreichende Menge, vollständige Benetzung und Einwirkzeit nach Produktangabe','Sofort abwischen','Nur die Handflächen benetzen','Handschuhe ersetzen die Desinfektion'],0,'Alle Handbereiche müssen für die vorgeschriebene Zeit benetzt sein. Handschuhe ersetzen Händedesinfektion nicht.']]},
  {title:'Subkutane Injektion sicher vorbereiten',steps:[['Was klärst du vor der Vorbereitung?',['Identität, Verordnung, Medikament, Dosis, Allergien und Einwilligung','Nur den Dienstplan','Nur die Farbe der Verpackung','Die Dosis nach Gefühl'],0,'Sicherheitsprüfungen und gültige Anordnung sind vor jeder Gabe erforderlich.'],['Was ist bei der Einstichstelle wichtig?',['Geeignete Stelle nach Standard wählen, Haut beurteilen und Rotationsplan beachten','Immer in dieselbe Stelle injizieren','Entzündete Stelle bevorzugen','Ohne Händehygiene arbeiten'],0,'Stellenwahl und Rotation richten sich nach Präparat, Körperstelle, Hautzustand und lokalem Standard.']]},
  {title:'Transfer vom Bett in den Rollstuhl',steps:[['Was planst du zuerst?', ['Wunsch, Fähigkeiten, Schmerzen, Hilfsmittel und erforderliche Unterstützung einschätzen','Sofort an den Armen ziehen','Hilfsmittel grundsätzlich weglassen','Transfer ohne Erklärung beginnen'],0,'Vor dem Transfer werden Ressourcen, Risiken, Einwilligung und geeignete Hilfsmittel geklärt.'],['Welche Ausführung unterstützt Sicherheit?', ['Bremse und Umgebung prüfen, verständlich anleiten und Bewegung passend begleiten','Rollstuhl ungebremst lassen','Person unbeaufsichtigt aufstehen lassen','Bei Schmerz weitermachen'],0,'Sichere Umgebung, klare Kommunikation und Beobachtung der Belastbarkeit sind wesentlich.']]},
  {title:'Sterile Wundversorgung',steps:[['Was ist vor dem sterilen Arbeiten zentral?', ['Indikation, Material, Hygieneplan und benötigte sterile Arbeitsweise klären','Sterile Materialien auf beliebiger Fläche ablegen','Handschuhe als Ersatz für Händedesinfektion sehen','Wunde ohne Erklärung freilegen'],0,'Vorbereitung, Händehygiene, aseptisches Arbeiten und Wahrung der Intimsphäre gehören zusammen.'],['Was dokumentierst du?', ['Wundbeobachtung, Maßnahme, Verträglichkeit und relevante Veränderungen','Nur „gemacht“','Keine Veränderungen','Nur die verwendete Handschuhgröße'],0,'Dokumentiert werden Befund, Durchführung, Wirkung und notwendige Weitergabe.']]},
  {title:'Vitalzeichen und Verschlechterung',steps:[['Ein Wert weicht stark vom bisherigen Zustand ab. Was tust du?', ['Messung/Technik prüfen, Person klinisch beurteilen und nach Dringlichkeit eskalieren','Wert löschen','Nur den Durchschnitt der Station vergleichen','Bis zum nächsten Tag warten'],0,'Ein auffälliger Messwert wird im klinischen Kontext geprüft; bei Warnzeichen wird sofort Hilfe organisiert.']]},
  {title:'Mundpflege bei eingeschränkter Schluckfähigkeit',steps:[['Was ist vor der Mundpflege zu beachten?', ['Wachheit, Schluckrisiko, Lagerung, Wünsche und individuellen Plan beachten','Flüssigkeit zügig einflößen','Person flach lagern','Mundpflege bei Widerstand erzwingen'],0,'Aspirationsrisiko, Einwilligung und sichere Position müssen berücksichtigt werden.']]},
  {title:'Schutzkleidung im Isolationszimmer',steps:[['Woran orientierst du die Auswahl?', ['Übertragungsweg, Erreger, Tätigkeit und lokalen Hygieneplan','An der Farbe der Tür','Immer dieselbe Schutzkleidung für alle Situationen','Nur am Wunsch der Besuchenden'],0,'Schutzmaßnahmen richten sich nach Erreger, Tätigkeit und betrieblichem Hygieneplan.']]},
  {title:'Medikamentengabe und Rückfrage',steps:[['Die Verordnung ist unklar. Wie handelst du?', ['Gabe zurückstellen, Rückfrage bei zuständiger Stelle und Klärung dokumentieren','Dosis selbst schätzen','Kolleginnen nach Vermutung fragen und geben','Medikament austauschen'],0,'Unklare Anordnungen werden vor der Gabe geklärt; keine eigenmächtige Dosisänderung.']]}
 ];
 let ch=0,chStep=0,chFeedback=false;
 function renderChallenges(c){
  const x=challenges[ch],s=x.steps[chStep];
  c.innerHTML='<div class="panel"><span class="tag">Praxis-Challenges · Schritt für Schritt</span><h2>Fachgerecht handeln und den Grund verstehen</h2><p>Jede Challenge erklärt nach deiner Wahl den fachlichen Grund und mögliche Risiken. Praktische Handgriffe müssen zusätzlich in der Ausbildungseinrichtung angeleitet und geübt werden.</p><div class="grid">'+challenges.map((z,i)=>'<button class="card" onclick="upgradeChallengeSelect('+i+')">'+(i===ch?'✓ ':'')+esc(z.title)+'</button>').join('')+'</div><div class="card"><h3>'+esc(x.title)+'</h3><p>Schritt '+(chStep+1)+' von '+x.steps.length+'</p><h3>'+esc(s[0])+'</h3>'+s[1].map((o,i)=>'<button class="option" '+(chFeedback?'disabled':'')+' onclick="upgradeChallengeChoose('+i+')">'+esc(o)+'</button>').join('')+(chFeedback?'<p class="'+(state.challengeResults[ch+'-'+chStep]?'good':'bad')+'">'+esc(s[3])+'</p><button class="btn primary" onclick="upgradeChallengeNext()">Nächster Schritt</button>':'')+'</div>';
 }
 window.upgradeChallengeSelect=i=>{ch=i;chStep=0;chFeedback=false;renderChallenges($('#content'))};
 window.upgradeChallengeChoose=i=>{if(chFeedback)return;state.challengeResults[ch+'-'+chStep]=i===challenges[ch].steps[chStep][2];safeSave();chFeedback=true;renderChallenges($('#content'))};
 window.upgradeChallengeNext=()=>{chStep++;if(chStep>=challenges[ch].steps.length){chStep=0;ch=(ch+1)%challenges.length}chFeedback=false;renderChallenges($('#content'))};

 // Prüfungsformate: schriftlich ausführliche Fälle und Operatoren; mündlich komplexe Fälle.
 // Die praktische Prüfung ist ausschließlich ein Hinweis auf Üben im eigenen Ausbildungseinsatz.
 const writtenCases=[
 {title:'Schriftliche Übung 1 · Pflegeprozess und Beziehung',focus:'Schlaganfall, Kommunikation, Selbstbestimmung, Mobilität und Übergang nach Hause',story:'Herr M., 58 Jahre, lebt mit seiner Partnerin in einer Wohnung im dritten Stock ohne Aufzug. Vor sechs Wochen erlitt er einen ischämischen Schlaganfall. In der neurologischen Rehabilitation sind eine rechtsseitige Schwäche und eine expressive Aphasie zurückgeblieben. Er versteht nach eigener Aussage vieles, braucht aber Zeit, um Worte zu finden. Vor dem Ereignis arbeitete er als selbstständiger Tischler und übernahm den Großteil der Hausarbeit. Seine Partnerin arbeitet in Teilzeit und betreut zusätzlich ihre Mutter. Sie berichtet, seit dem Schlaganfall nachts häufig aufzuwachen, weil sie Angst hat, Herr M. könne aus dem Bett fallen.\n\nBeim Frühdienst sitzt Herr M. angezogen am Bettrand. Er hält sich mit der linken Hand fest und sagt stockend: „Alleine… Bad.“ Die Partnerin antwortet sofort: „Das geht nicht, er fällt gleich wieder hin.“ Herr M. wendet den Blick ab und schiebt den Rollator weg. Bei der Morgenpflege zieht er die Decke hoch und sagt: „Lassen Sie mich in Ruhe.“ In der Übergabe steht, dass er am Vortag mit Unterstützung einer Pflegefachperson bis zum Waschbecken gehen konnte. Eine physiotherapeutische Einschätzung beschreibt eine teilweise belastbare rechte Seite; zu Hause seien drei Stufen am Hauseingang zu überwinden. Derzeit ist nicht geklärt, wie Herr M. seine Einwilligung in einzelne Pflegeschritte am besten ausdrücken kann.\n\nBeim Frühstück verschluckt er sich einmal an dünnem Tee und hustet kurz. Er wirkt danach angespannt, nimmt aber einen Joghurt selbstständig zu sich. Eine strukturierte Schluckbeurteilung liegt nicht in der aktuellen Akte. Die Partnerin möchte, dass er pürierte Kost bekommt und nicht mehr allein aufsteht. Herr M. zeigt auf sein normales Brot und schüttelt den Kopf, als die Partnerin es wegstellt. Seine Vitalzeichen sind stabil; Schmerzen verneint er durch Kopfschütteln. Angaben zu seiner bevorzugten Kommunikationsform, Schluckdiagnostik, Hilfsmittelbedarf, häuslicher Unterstützung und seinem eigenen Rehabilitationsziel fehlen. Das interprofessionelle Team plant in drei Wochen eine Entlassung, falls die Versorgung zu Hause sicher organisiert werden kann. Herr M. soll an Entscheidungen beteiligt werden; seine Partnerin benötigt zugleich Raum, Belastungen und Unterstützungsbedarf anzusprechen.'},
 {title:'Schriftliche Übung 2 · Beratung und Gesundheitsförderung',focus:'Kind nach Operation, Schmerz, Mobilisation, Angehörigenberatung und altersgerechte Beteiligung',story:'Der neunjährige Leo liegt am ersten postoperativen Tag nach einer laparoskopischen Appendektomie auf einer Kinderstation. Die Operation verlief ohne berichtete Komplikation. Leo lebt mit seinen Eltern und einer älteren Schwester. Er geht gern Fußball spielen und möchte schnell nach Hause. Seine Mutter war während der Nacht bei ihm und wirkt müde. Sie sorgt sich, Bewegung könne die Wunde öffnen. Der Vater kann erst am Abend kommen und hat am Telefon nach der Entlassung gefragt.\n\nAm Vormittag möchte Leo zum Fenster gehen. Beim Aufrichten verzieht er das Gesicht und sagt, es ziehe am Bauch. Er möchte zunächst sitzen bleiben und selbst bestimmen, wann die nächste Pause kommt. Die Pflegefachperson sieht einen trockenen Verband; Leo ist fieberfrei und ansprechbar. Er hat seit dem Vorabend nur wenig getrunken und den größten Teil des Frühstücks stehen lassen. Im Dokumentationssystem wurde die letzte Schmerzbeurteilung vor mehreren Stunden erfasst. Die aktuelle Schmerzstärke, Übelkeit, Kreislaufreaktion und ärztliche Mobilisationsvorgaben müssen erhoben beziehungsweise geprüft werden.\n\nDie Mutter sagt: „Er muss im Bett bleiben, dann heilt es schneller.“ Leo schaut zur Mutter und sagt leise, dass er Angst vor Schmerzen hat und nicht weiß, wie er aufstehen soll. Er fragt, ob er etwas tun kann, um schneller nach Hause zu dürfen. Die Eltern wünschen verständliche Erklärungen ohne Fachwörter. Leo liest kurze Sätze selbst, versteht Bilder gut und möchte, dass man zuerst mit ihm spricht. Zu seinem Vorwissen, seinen Sorgen und den Regeln für Trinken, Essen und Mobilisation nach dem Eingriff liegen nur teilweise Informationen vor.\n\nDie Pflegefachperson möchte ein kurzes Beratungsangebot planen, Leo beteiligen und seine Mutter entlasten. Sie muss dabei die postoperative Situation, mögliche Warnzeichen, die ärztliche Anordnung und die individuelle Belastbarkeit beachten. Es soll nicht versprochen werden, dass eine bestimmte Handlung automatisch zur Entlassung führt. Die Wirkung der Beratung soll gemeinsam mit Leo überprüft werden: Versteht er die nächsten Schritte? Kann er sagen, wann er Hilfe oder eine Pause braucht? Wie verändern sich Schmerz, Kreislauf, Bewegung und Trinkmenge?'},
 {title:'Schriftliche Übung 3 · Kritische Situation, Zusammenarbeit und Ethik',focus:'Akute Zustandsveränderung, strukturierte Einschätzung, Eskalation und Entscheidungsabwägung',story:'Herr B., 79 Jahre, lebt seit vier Jahren in einer stationären Pflegeeinrichtung. Er hat eine chronische Herzinsuffizienz, eine eingeschränkte Nierenfunktion und eine leichte kognitive Beeinträchtigung. Gewöhnlich ist er morgens orientiert, spricht gern über seinen früheren Beruf als Busfahrer und geht mit Rollator zum Frühstück. In den letzten Tagen war er wegen eines Atemwegsinfekts weniger aktiv. Ein aktueller Medikamentenplan liegt vor; Änderungen der letzten Woche und die üblichen Vitalwerte sollen überprüft werden.\n\nWährend des Spätdienstes findet eine Pflegefachperson Herrn B. im Flur sitzend vor. Er ist blass, atmet schneller als üblich und sagt, ihm sei schwindelig. Er wirkt ungewohnt unruhig und kann nicht erklären, warum er den Raum verlassen wollte. Beim Aufstehen hält er sich am Tisch fest. Eine Pflegehilfskraft möchte den nächsten Rundgang abwarten, da Herr B. am Morgen noch unauffällig gewesen sei. Seine Tochter trifft ein und fordert, sofort ein Bettgitter anzubringen und ihn im Bett festzuhalten, damit er nicht stürzt. Herr B. sagt: „Ich will hier nicht eingesperrt werden.“\n\nEs liegen noch keine aktuellen Vitalwerte vor. Ob Brustschmerz, Fieber, Flüssigkeitsmangel, eine Medikamentenwirkung, eine Infektverschlechterung oder eine andere Ursache vorliegt, ist offen. Der letzte dokumentierte Trinkbecher war am frühen Nachmittag. Ein Sturz oder eine Verletzung wurde noch nicht festgestellt. Die Einrichtung hat einen internen Alarmierungsweg; ein ärztlicher Bereitschaftsdienst ist erreichbar. Die Pflegefachperson muss die akute Veränderung ernst nehmen, Herrn B. sichern und Unterstützung organisieren, ohne vorschnell eine Ursache festzulegen.\n\nDie Tochter ist besorgt und möchte helfen. Herr B. ist jedoch ansprechbar und äußert einen eigenen Willen. Es muss situationsbezogen geprüft werden, welche Informationen er versteht und welche Entscheidungen er selbst treffen kann. Das Team soll seine Sicherheit wahren, mildere geeignete Maßnahmen berücksichtigen und die Tochter respektvoll einbeziehen. Verlauf, Beobachtungen, Rückmeldungen, Anordnungen und die Wirkung der Maßnahmen sind nachvollziehbar zu dokumentieren.'}
 ];

 writtenCases[0].story+='\n\nIm Pflegebericht finden sich folgende ergänzende Angaben: Herr M. trägt eine Brille und hört auf dem linken Ohr schlechter. Bei längeren Gesprächen ermüdet er; am Nachmittag kann er sich meist besser ausdrücken als direkt nach dem Aufstehen. Er verwendet gelegentlich ein kleines Bild- und Buchstabenbrett, das er während der Rehabilitation selbst ausgewählt hat. Wenn mehrere Fragen schnell hintereinander gestellt werden, nickt er manchmal, obwohl später deutlich wird, dass er nicht alles verstanden hat. Seine Partnerin kennt seine übliche Gestik gut, übernimmt aber häufig aus Sorge das Gespräch.\n\nAm Vortag wurde beim begleiteten Transfer eine leichte Unsicherheit beim Drehen beobachtet. Der Rollator war erreichbar, jedoch stand der Bremshebel nicht vollständig festgestellt. Herr M. konnte mit Zeit und verbaler Anleitung einen Teil der Körperpflege selbst übernehmen. Die Pflegekraft dokumentierte, dass er bei einem vertrauten Ablauf weniger Unterstützung brauchte. Zum Essen liegen keine standardisierten Angaben zu Kostform, Schluckfähigkeit oder geeigneter Sitzposition vor. Die einmalige Hustenepisode ist bislang nicht fachlich abgeklärt.\n\nHerr M. hat im Gespräch mit der Ergotherapie gesagt, dass er wieder selbst am Frühstückstisch sitzen und seine Werkstatt zu Hause besuchen möchte. Die Partnerin möchte ihn unterstützen, fürchtet aber, die Versorgung allein nicht bewältigen zu können. Ein ambulanter Pflegedienst wurde noch nicht angefragt; der Hauseingang und das Treppenhaus wurden bisher nicht gemeinsam besichtigt. Angehörigenberatung und Hilfsmittelversorgung sind mögliche Themen für die Entlassungsplanung. Die Aussagen der Partnerin dürfen die eigene Sicht und Entscheidung von Herrn M. nicht ersetzen.';
 writtenCases[1].story+='\n\nDie postoperative Anordnung sieht eine frühe, am Zustand orientierte Mobilisation vor; die genaue Belastbarkeit und der Zeitpunkt weiterer Schritte müssen dennoch mit dem Behandlungsteam abgestimmt werden. Leo hat bislang keine kindgerechte Erklärung zum Schmerzmittelplan erhalten. Die Mutter kann sich an eine frühere Operation eines Familienmitglieds erinnern und verbindet Bewegung mit einer möglichen Wundöffnung. Sie fragt, ob Leo bis zur Entlassung dauerhaft überwacht werden muss. Der Vater hat wenig Erfahrung mit der Versorgung nach Operationen und möchte am Abend eine verständliche Zusammenfassung bekommen.\n\nBei der Übergabe wurde notiert, dass Leo in der Nacht wegen Bauchschmerzen einmal aufgewacht ist. Eine aktuelle standardisierte Schmerzeinschätzung, der Verlauf nach verordnetem Schmerzmittel und die Verträglichkeit der Nahrung fehlen. Die Pflegefachperson hat beobachtet, dass Leo bei einem kurzen Gespräch gern selbst Fragen stellt, wenn die Mutter nicht sofort antwortet. Seine Schwester hat ihm ein Bild vom Fußballplatz geschickt, das er am Bett aufgestellt hat. Diese Interessen können als Gesprächs- und Motivationsressource genutzt werden, ohne eine schnelle Entlassung zu versprechen.\n\nVor der Beratung müssen die gültigen ärztlichen Vorgaben, die Regeln zur Kost- und Flüssigkeitsaufnahme sowie der aktuelle klinische Zustand geprüft werden. Für die Einschätzung sind außerdem Leos individuelle Schmerzaussage, seine Angst, die Kreislaufreaktion beim Aufrichten und mögliche Veränderungen am Bauch relevant. Die Familie benötigt einen Plan, an wen sie sich bei Warnzeichen wenden kann. Die Pflegefachperson soll Informationen in einfacher Sprache vermitteln und Verständnis prüfen, statt nur einen Merkzettel auszuhändigen.';
 writtenCases[2].story+='\n\nBei Herrn B. wurde vor einer Woche ein neues entwässerndes Medikament angesetzt. Ob Dosis und Einnahmezeiten seither korrekt umgesetzt wurden, ist aus der Übergabe nicht ersichtlich. Ein aktueller Medikamentenabgleich ist erforderlich; eigenständige Änderungen durch die Pflege sind ausgeschlossen. Die Tochter berichtet, ihr Vater habe am Vortag weniger getrunken und nachts mehrfach die Toilette gesucht. Diese Angaben sind wichtige Hinweise, klären die Ursache der aktuellen Veränderung aber nicht.\n\nIm Wohnbereich befinden sich ein Rollator, eine Rufanlage und ein gut beleuchteter Gemeinschaftsraum. Herr B. kann die Rufanlage gewöhnlich bedienen, legt sie beim Gehen aber manchmal auf den Tisch. Er trägt eine Brille und benötigt beim Hören eine ruhige Umgebung. In früheren Gesprächen äußerte er, dass er bei Schwindel lieber begleitet wird. Ob er diese Präferenz aktuell bestätigen kann und welche Unterstützung er jetzt annimmt, ist direkt bei ihm zu erfragen. Ein Bettgitter würde seine Sturzgefahr nicht automatisch beseitigen und könnte zusätzliche Risiken schaffen.\n\nFür die ärztliche Rückmeldung müssen Verlauf, mögliche Infektzeichen, Atmung, Kreislauf, Flüssigkeit, Ausscheidung, Schmerzen und Medikamentenänderungen zusammengetragen werden. Das Team muss zudem klären, wer bei Herrn B. rechtlich vertretungsberechtigt ist, falls er eine konkrete Entscheidung nicht selbst treffen kann; die bloße Anwesenheit der Tochter begründet keine pauschale Entscheidungsbefugnis. Bis zur Klärung sind sein Wille, seine Sicherheit und die mildeste geeignete Unterstützung zu beachten.';
 const oralGuides=[
  ['KB III – Zusammenarbeit: Samira zuerst selbst ansprechen und mit ihr ein vertrauliches Gespräch anbieten. Ärztlicher Dienst klärt medizinische Fragen; Pflege erhebt Alltag, Belastung und Unterstützungswünsche; Schulsozialarbeit nur mit Samiras Einverständnis einbeziehen.','KB III – Qualität und Kontinuität: gemeinsam einen erreichbaren Kontrolltermin und einen vereinbarten Kontaktweg planen. Wirkung an wahrgenommenen Terminen, Samiras Verständnis und ihrer selbst eingeschätzten Belastung prüfen.','KB IV – Vertraulichkeit: Informationen nicht automatisch vollständig an die Mutter weitergeben. Samiras Einwilligungsfähigkeit und der konkrete Umfang einer möglichen Freigabe situationsbezogen prüfen und dokumentieren.','KB IV – Ethische Abwägung: Selbstbestimmung und Schutz vor gesundheitlichem Schaden abwägen, ohne Kontrolle pauschal anzuordnen. Samira altersgerecht informieren und mögliche Risiken verständlich besprechen.','KB V – Fachwissen: aktuelle Leitlinien und lokale Standards zu Typ-1-Diabetes, Hypoglykämie und Jugendtransition heranziehen; Aktualität und Übertragbarkeit prüfen.','KB V – Berufsrolle: wertfrei nach Gründen für versäumte Termine fragen; mögliche organisatorische, emotionale oder finanzielle Hürden erkunden und eigene Vorannahmen reflektieren.'],
  ['KB III – Zusammenarbeit: Pflege koordiniert Beobachtung und Gespräch; ärztlicher Dienst prüft akute Verschlechterung und Medikation; weitere Berufsgruppen nach Bedarf. Den Sohn nur passend zu Frau R.s Wunsch und rechtlicher Grundlage beteiligen.','KB III – Qualität: nächtliche Atemnot, Schwindel, Vitalwerte, Flüssigkeit, Ausscheidung und Alltag systematisch erfassen; vereinbarte Maßnahmen und Wirkung evaluieren.','KB IV – Selbstbestimmung: Frau R. direkt ansprechen und ihre Bitte um ein Gespräch unter vier Augen respektieren, sofern keine konkrete entgegenstehende Rechtsgrundlage besteht.','KB IV – Einwilligung und Schutz: Entscheidungsfähigkeit ist konkret und situationsbezogen zu beurteilen. Eine kognitive Beeinträchtigung allein hebt Selbstbestimmung nicht auf; bei akuter Gefahr Hilfe organisieren.','KB V – Evidenz: aktuelle fachliche Empfehlungen zu Herzinsuffizienz, chronischer Nierenerkrankung und Medikationssicherheit heranziehen; lokale Standards beachten und keine Therapie eigenständig ändern.','KB V – Berufsrolle: den Konflikt mit dem Sohn ruhig moderieren, Grenzen und Schweigepflicht erklären und eigene Haltung zu Selbstbestimmung und Risiko kritisch prüfen.']
 ];

